text:
$$
\mathcal {L} _ {\mathrm{I2T}} = - \frac {1}{N} \sum_ {i = 1} ^ {N} \log \frac {\exp [ (\pmb {v} _ {i} \cdot \pmb {t} _ {i}) / \tau ]}{\sum_ {j = 1} ^ {N} \exp [ (\pmb {v} _ {i} \cdot \pmb {t} _ {j}) / \tau ]},\tag{1}
$$

$$
\mathcal {L} _ {\mathrm{T2I}} = - \frac {1}{N} \sum_ {j = 1} ^ {N} \log \frac {\exp [ (\boldsymbol {v} _ {j} \cdot \boldsymbol {t} _ {j}) / \tau ]}{\sum_ {i = 1} ^ {N} \exp [ (\boldsymbol {v} _ {i} \cdot \boldsymbol {t} _ {j}) / \tau ]}.\tag{2}
$$

$$
\mathcal {L} _ {\mathrm{CLIP}} = \frac {1}{2} \left(\mathcal {L} _ {\mathrm{I2T}} + \mathcal {L} _ {\mathrm{T2I}}\right).\tag{3}
$$

$$
\mathrm{ConsistencyScore} _ {k} = \frac {1}{N} \sum_ {i = 1} ^ {N} \mathbb {1} [ P _ {I} ^ {k} (I _ {i}) = P _ {T} (I _ {i}) ],\tag{4}
$$

$$
\mathcal {L} _ {\mathrm{C-Cyclic}} = \frac {1}{N} \sum_ {i = 1} ^ {N} \sum_ {j = 1} ^ {N} \left(\boldsymbol {v} _ {i} \cdot \boldsymbol {t} _ {j} - \boldsymbol {v} _ {j} \cdot \boldsymbol {t} _ {i}\right) ^ {2}.\tag{5}
$$

$$
\mathcal {L} _ {\mathrm{I-Cyclic}} = \frac {1}{N} \sum_ {i = 1} ^ {N} \sum_ {j = 1} ^ {N} \left(\boldsymbol {v} _ {i} \cdot \boldsymbol {v} _ {j} - \boldsymbol {t} _ {j} \cdot \boldsymbol {t} _ {i}\right) ^ {2}.\tag{6}
$$

$$
\mathcal {L} _ {\text {C - Cyclic}} ^ {\text {intra}} = \frac {1}{| \mathcal {S} |} \sum_ {((I _ {i} ^ {k}, T _ {i} ^ {k}), (I _ {j} ^ {k}, T _ {j} ^ {k})) \in \mathcal {S}} \left(\boldsymbol {v} _ {i} ^ {k} \cdot \boldsymbol {t} _ {j} ^ {k} - \boldsymbol {v} _ {j} ^ {k} \cdot \boldsymbol {t} _ {i} ^ {k}\right) ^ {2}.\tag{10}
$$

$$
\mathcal {L} _ {\text {I - Cyclic}} ^ {\text {intra}} = \frac {1}{| \mathcal {S} |} \sum_ {((I _ {i} ^ {k}, T _ {i} ^ {k}), (I _ {j} ^ {k}, T _ {j} ^ {k})) \in \mathcal {S}} \left(\boldsymbol {v} _ {i} ^ {k} \cdot \boldsymbol {v} _ {j} ^ {k} - \boldsymbol {t} _ {j} ^ {k} \cdot \boldsymbol {t} _ {i} ^ {k}\right) ^ {2},\tag{11}
$$

$$
\mathcal {L} _ {\mathrm{intra}} = \mathcal {L} _ {\mathrm{I-Cyclic}} ^ {\mathrm{intra}} + \mathcal {L} _ {\mathrm{C-Cyclic}} ^ {\mathrm{intra}}\tag{12}
$$

$$
\pmb {v} _ {\mathrm{proto}} ^ {k} = \frac {1}{N _ {k} ^ {b}} \sum_ {i = 1} ^ {N _ {k} ^ {b}} \pmb {v} _ {i} ^ {k}, \quad \pmb {t} _ {\mathrm{proto}} ^ {k} = \frac {1}{N _ {k} ^ {b}} \sum_ {i = 1} ^ {N _ {k} ^ {b}} \pmb {t} _ {i} ^ {k},\tag{13}
$$

$$
\mathcal{L}_{\mathrm{C - Cyclic}}^{\mathrm{inter},k,i} = \frac{1}{K - 1}\sum_{\substack{m = 1\\ m\neq k}}^{K}\left(\boldsymbol{v}_{i}^{k}\cdot \boldsymbol{t}_{\mathrm{proto}}^{m} - \boldsymbol{v}_{\mathrm{proto}}^{m}\cdot \boldsymbol{t}_{i}^{k}\right)^{2},\tag{14}
$$

$$
\mathcal{L}_{\text{I - Cyclic}}^{\text{inter},k,i} = \frac{1}{K - 1}\sum_{\substack{m = 1\\ m\neq k}}^{K}\left(\boldsymbol{v}_{i}^{k}\cdot \boldsymbol{v}_{\text{proto}}^{m} - \boldsymbol{t}_{\text{proto}}^{m}\cdot \boldsymbol{t}_{i}^{k}\right)^{2}.\tag{15}
$$

$$
\mathcal {L} _ {\mathrm{inter}} = \frac {1}{N} \sum_ {k = 1} ^ {K} \sum_ {i = 1} ^ {N _ {k} ^ {b}} \left(\mathcal {L} _ {\mathrm{C-Cyclic}} ^ {\mathrm{inter}, k, i} + \mathcal {L} _ {\mathrm{I-Cyclic}} ^ {\mathrm{inter}, k, i}\right).\tag{16}
$$

$$
\mathcal {L} _ {\mathrm{total}} = \mathcal {L} _ {\mathrm{CLIP}} + \lambda_ {1} \cdot \mathcal {L} _ {\mathrm{intra}} + \lambda_ {2} \cdot \mathcal {L} _ {\mathrm{inter}},\tag{17}
$$
